"""
build_extreme_events.py - library of extreme operational-risk loss events,
focused on financial markets (trading & sales) and operations / back office.

Scope: all geographies, 1985-2026, loss or exposure of USD 20m or more, at
banks, broker-dealers, asset managers, market infrastructure, crypto venues
and corporate / public trading desks (the last flagged by firm_type so they
can be filtered out).

Output: extreme_events.csv (one row per event; several fines for the same
case at the same firm are one event).

Amounts are as publicly reported, in millions of the original currency.
USD conversion uses approximate annual average rates of the year the loss was
announced (FX table below) - good to about +/-5%, enough for scenario work.
Market-risk losses with no operational failure (e.g. LTCM, Amaranth) are
excluded on purpose.
"""
import csv
from pathlib import Path

# approximate annual average USD per unit of currency, by year announced
FX = {
    "USD": {},
    "GBP": {1995: 1.58, 1996: 1.56, 1997: 1.64, 2010: 1.55, 2012: 1.58, 2013: 1.56, 2014: 1.65, 2015: 1.53,
            2016: 1.36, 2017: 1.29, 2018: 1.34, 2019: 1.28, 2022: 1.24, 2023: 1.24, 2024: 1.28},
    "EUR": {2004: 1.24, 2006: 1.26, 2007: 1.37, 2008: 1.47, 2015: 1.11, 2016: 1.11, 2018: 1.18},
    "JPY": {1993: 1 / 111, 1994: 1 / 102, 1996: 1 / 109, 2005: 1 / 110},
    "CAD": {2007: 0.93},
    "AUD": {2004: 0.74},
    "HKD": {2008: 0.128},
    "SEK": {2010: 0.139},
    "SGD": {2020: 0.725},
    "CNY": {2013: 0.161},
}


def usd(amount, ccy, year):
    if amount is None:
        return None
    return round(amount * (1.0 if ccy == "USD" else FX[ccy][year]), 1)


